public class MainActivity extends Activity {
 private static final String HOME_URL="https://dsdidar79-dev.github.io/onlineservicebd/";
 private WebView webView; private ValueCallback<Uri[]> fileCallback; private static final int FILE_REQUEST=1001;
 @Override protected void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff0f172a);getWindow().setNavigationBarColor(0xff0f172a);webView=new WebView(this);setContentView(webView);
 WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setJavaScriptCanOpenWindowsAutomatically(true);s.setSupportMultipleWindows(false);s.setLoadsImagesAutomatically(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
 CookieManager cm=CookieManager.getInstance();cm.setAcceptCookie(true);cm.setAcceptThirdPartyCookies(webView,true);
 webView.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return route(r.getUrl().toString());}@SuppressWarnings("deprecation") @Override public boolean shouldOverrideUrlLoading(WebView v,String u){return route(u);}@Override public void onPageFinished(WebView v,String url){super.onPageFinished(v,url);if(url.startsWith(HOME_URL))installAppDesign();}});
 webView.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;try{startActivityForResult(p.createIntent(),FILE_REQUEST);return true;}catch(Exception e){fileCallback=null;Toast.makeText(MainActivity.this,"ফাইল নির্বাচন করা যাচ্ছে না",Toast.LENGTH_SHORT).show();return false;}}});
 webView.setDownloadListener((u,ua,cd,mt,len)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){Toast.makeText(this,"ডাউনলোড লিংক খোলা যাচ্ছে না",Toast.LENGTH_SHORT).show();}});
 if(state==null)webView.loadUrl(HOME_URL);else webView.restoreState(state);
 }

 private void installAppDesign(){
  String js="(function(){\n if(!document.getElementById('osbAppStyle')){var st=document.createElement('style');st.id='osbAppStyle';st.textContent=\":root{--app-navy:#06254d;--app-blue:#0878c9;--app-bg:#edf5fc;--app-ink:#102b49}html,body{background:var(--app-bg)!important;color:var(--app-ink)!important;font-family:Arial,'Noto Sans Bengali',sans-serif!important}body{padding-bottom:92px!important}header{background:linear-gradient(145deg,#041b3b,#07549a)!important;box-shadow:0 5px 18px #05254b30!important}header .nav{padding:10px 13px!important;min-height:68px!important}.logo-mark{width:48px!important;height:48px!important}.logo-copy strong{font-size:18px!important;color:white!important}.logo-copy small{color:#ffdb37!important}.user-top-bar{background:#062b59!important;color:white!important;padding:8px 10px!important}#dashboardContainer{width:100%!important;max-width:100%!important;margin:0!important;padding:10px 11px 25px!important;box-sizing:border-box!important;background:var(--app-bg)!important}.main-flex-layout{display:flex!important;flex-direction:column!important;gap:11px!important;height:auto!important;overflow:visible!important}.left-sidebar,.right-content{display:contents!important;width:100%!important;height:auto!important;overflow:visible!important}.dash-box,.content-card{background:#fff!important;color:var(--app-ink)!important;border:1px solid #dce9f5!important;border-radius:18px!important;box-shadow:0 4px 13px #082f5510!important;padding:13px!important;margin:0 0 11px!important}.dash-box h3,.dash-box h4,.dash-box p,.content-card h3,.content-card p{color:var(--app-ink)!important}.sidebar-nav-box{display:none!important}.service-list{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:9px!important}.service-item-link{background:#f8fbff!important;border:1px solid #dce9f6!important;border-radius:15px!important;padding:11px 9px!important;min-height:76px!important;display:flex!important;flex-direction:column!important;justify-content:center!important;box-shadow:0 3px 9px #092f5510!important}.service-item-link h4{font-size:13px!important;font-weight:800!important;margin:0!important;line-height:1.4!important}.service-item-link p{font-size:10px!important;line-height:1.4!important;margin:4px 0 0!important;color:#64748b!important}#osbAppHero{display:flex;align-items:center;gap:12px;padding:15px 13px;margin:1px 0 11px;border-radius:20px;background:linear-gradient(135deg,#06254d,#07569c);color:#fff;box-shadow:0 7px 18px #06254d24}#osbAppHero .brandmark{width:58px;height:58px;flex:0 0 58px;border-radius:18px;display:grid;place-items:center;background:linear-gradient(135deg,#11b9ec,#ffda38);font-size:31px;color:#06254d}#osbAppHero .brandtitle{font-size:20px;font-weight:900;line-height:1.35;color:#fff}#osbAppHero .brandtitle small{display:block;color:#ffdf43;letter-spacing:1px;font-size:11px}#osbAppHero .hello{font-size:13px;margin-top:6px;color:#eaf5ff}#osbAppBalance{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:15px;margin:0 0 12px;border:1px solid #21b8ed;border-radius:20px;background:linear-gradient(120deg,#0787d4,#064c9b);color:#fff;box-shadow:0 7px 17px #00539b28}#osbAppBalance .bal-label{font-size:14px;font-weight:700;color:#fff}#osbAppBalance .bal-value{font-size:29px;font-weight:900;color:#ffdf36;line-height:1.3}#osbAppBalance button{border:0;border-radius:30px;background:#fff;color:#06447f;padding:11px 13px;font-weight:800;font-size:12px;white-space:nowrap}#osbAppSearch{display:flex;gap:7px;align-items:center;background:#fff;border:1px solid #d8e7f5;border-radius:16px;padding:6px 8px;margin:0 0 12px;box-shadow:0 3px 10px #082f5510}#osbAppSearch input{border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;flex:1;min-width:0;padding:9px!important;font-size:14px!important;color:#102b49!important}#osbAppSearch button{border:0;border-radius:12px;background:#087bc6;color:#fff;padding:9px 13px;font-size:18px}#osbAppShortcuts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:0 0 13px}#osbAppShortcuts button{display:flex;align-items:center;justify-content:space-between;gap:6px;border:1px solid #d9e8f5;border-radius:16px;background:#fff;color:#102b49;padding:12px 10px;min-height:76px;text-align:left;font-weight:800;box-shadow:0 4px 10px #082f5510;font-size:12px}#osbAppShortcuts .shortcut-icon{font-size:24px}#osbAppShortcuts .arrow{font-size:20px;color:#087bc6}#osbAppRecentTitle{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-radius:15px;background:#06254d;color:#fff;font-size:15px;font-weight:900;margin:0 0 8px}.dashboard-kpis{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important}.dashboard-kpi{background:#f1f7fd!important;border:1px solid #e0ebf5!important;border-radius:13px!important;padding:10px!important}.dashboard-kpi b{color:#0875b9!important}.app-bottom-nav{position:fixed;z-index:99999;left:9px;right:9px;bottom:7px;height:65px;border-radius:20px;background:linear-gradient(120deg,#061d3c,#082e60);display:flex;align-items:center;justify-content:space-around;box-shadow:0 8px 26px #0004;padding-bottom:env(safe-area-inset-bottom)}.app-bottom-nav button{border:0!important;background:transparent!important;color:#e7f2ff!important;font:600 10px Arial,sans-serif!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:2px!important;min-width:48px!important;padding:4px!important}.app-bottom-nav button b{font-size:21px;line-height:24px}.app-bottom-nav button.active{color:#13c9f1!important}.modal-overlay{padding:10px!important}.modal-card{max-height:90vh!important;overflow:auto!important;border-radius:19px!important}.action-btn{border-radius:13px!important}.floating-helpline{bottom:82px!important;right:12px!important}@media(min-width:650px){#dashboardContainer{max-width:600px!important;margin:auto!important}.app-bottom-nav{max-width:580px;left:50%;right:auto;transform:translateX(-50%)}}\";document.head.appendChild(st);}\n function visible(el){return !!el&&getComputedStyle(el).display!=='none'&&el.offsetWidth>0&&el.offsetHeight>0;}\n function setup(){\n  var root=document.getElementById('dashboardContainer');if(!visible(root))return;\n  if(!document.getElementById('osbAppHero')){\n   var hero=document.createElement('section');hero.id='osbAppHero';hero.innerHTML='<div class=\"brandmark\">🌐</div><div><div class=\"brandtitle\">অনলাইন সার্ভিস বিডি<small>ONLINE SERVICE BD</small></div><div class=\"hello\">আসসালামু আলাইকুম, <span id=\"osbHelloName\">স্বাগতম</span></div></div>';root.insertBefore(hero,root.firstChild);\n   var nm=document.getElementById('customerNameDisplay');if(nm)document.getElementById('osbHelloName').textContent=nm.textContent.trim();\n  }\n  if(!document.getElementById('osbAppBalance')){\n   var oldBal=document.getElementById('dashBalance'),balanceBox=oldBal&&oldBal.closest('.dash-box');\n   if(balanceBox){var w=document.createElement('section');w.id='osbAppBalance';w.innerHTML='<div><div class=\"bal-label\">💳 আমার ব্যালেন্স</div><div class=\"bal-value\">৳ <span id=\"osbBalVal\">0.00</span></div></div><button type=\"button\" id=\"osbRecharge\">＋ রিচার্জ করুন</button>';root.insertBefore(w,document.getElementById('osbAppHero').nextSibling);document.getElementById('osbBalVal').textContent=oldBal.textContent;document.getElementById('osbRecharge').onclick=function(){var b=document.getElementById('boxRechargeBtn');if(b)b.click();};balanceBox.style.display='none';}\n  }\n  if(!document.getElementById('osbAppSearch')){var search=document.createElement('div');search.id='osbAppSearch';search.innerHTML='<span style=\"font-size:21px\">⌕</span><input id=\"osbServiceSearch\" placeholder=\"আপনার প্রয়োজনীয় সেবা খুঁজুন...\"><button type=\"button\">⌕</button>';var bal=document.getElementById('osbAppBalance');root.insertBefore(search,bal?bal.nextSibling:document.getElementById('osbAppHero').nextSibling);}\n  if(!document.getElementById('osbAppShortcuts')){\n   var groups=Array.from(root.querySelectorAll('.left-sidebar .dash-box')).filter(function(x){return x.querySelector('.service-list');});\n   var shortcuts=document.createElement('div');shortcuts.id='osbAppShortcuts';var icons=['🪪','👶','📄','🗺️','🌱','📘','📂','🧾','📱','▦'];\n   groups.forEach(function(g,i){var h=g.querySelector('h3');var label=h?h.textContent.trim():'সকল সেবা';var bt=document.createElement('button');bt.type='button';bt.innerHTML='<span><span class=\"shortcut-icon\">'+icons[i%icons.length]+'</span><br>'+label+'</span><span class=\"arrow\">›</span>';bt.onclick=function(){g.scrollIntoView({behavior:'smooth',block:'start'});};shortcuts.appendChild(bt);});\n   var search=document.getElementById('osbAppSearch');if(search)root.insertBefore(shortcuts,search.nextSibling);\n  }\n  var input=document.getElementById('osbServiceSearch');if(input&&!input.dataset.bound){input.dataset.bound='1';input.addEventListener('input',function(){var q=this.value.toLowerCase().trim();root.querySelectorAll('.service-item-link').forEach(function(x){x.style.display=(!q||x.textContent.toLowerCase().includes(q))?'':'none';});});}\n  if(!document.getElementById('osbAppRecentTitle')){var table=document.getElementById('userOrderHistoryTable'),card=table&&table.closest('.dash-box');if(card){var title=document.createElement('div');title.id='osbAppRecentTitle';title.innerHTML='<span>◷ সাম্প্রতিক অর্ডার</span><span style=\"color:#13c9f1;font-size:11px\">সব দেখুন →</span>';root.insertBefore(title,card);}}\n  if(!document.getElementById('osbAppNav')){var nav=document.createElement('nav');nav.id='osbAppNav';nav.className='app-bottom-nav';nav.innerHTML='<button class=\"active\" data-go=\"home\"><b>⌂</b>হোম</button><button data-go=\"services\"><b>▦</b>সার্ভিস</button><button data-go=\"orders\"><b>▤</b>অর্ডার</button><button data-go=\"notify\"><b>♧</b>নোটিফাই</button><button data-go=\"profile\"><b>●</b>প্রোফাইল</button>';document.body.appendChild(nav);\n   nav.addEventListener('click',function(e){var b=e.target.closest('button[data-go]');if(!b)return;nav.querySelectorAll('button').forEach(function(x){x.classList.toggle('active',x===b);});var g=b.dataset.go;if(g==='home')window.scrollTo({top:0,behavior:'smooth'});if(g==='services'){var x=document.getElementById('osbAppShortcuts');if(x)x.scrollIntoView({behavior:'smooth'});}if(g==='orders'){var x=document.getElementById('userOrderHistoryTable');if(x&&x.closest('.dash-box'))x.closest('.dash-box').scrollIntoView({behavior:'smooth'});}if(g==='notify'){var x=document.getElementById('notifBtn');if(x)x.click();}if(g==='profile'){var x=document.getElementById('profileDetailsBtn');if(x)x.click();}});\n  }\n }\n function run(){setup();}run();var obs=new MutationObserver(function(){if(!document.getElementById('osbAppHero'))setup();});obs.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['style','class']});setInterval(function(){var r=document.getElementById('dashboardContainer');if(visible(r)&&!document.getElementById('osbAppHero'))setup();var a=document.getElementById('dashBalance'),b=document.getElementById('osbBalVal');if(a&&b&&b.textContent!==a.textContent)b.textContent=a.textContent;},1200);\n})();";
  webView.evaluateJavascript(js,null);
 }
 private boolean route(String raw){Uri u=Uri.parse(raw);String scheme=u.getScheme()==null?"":u.getScheme();if("http".equalsIgnoreCase(scheme)||"https".equalsIgnoreCase(scheme)){String h=u.getHost()==null?"":u.getHost().toLowerCase();if(h.equals("dsdidar79-dev.github.io")||h.equals("supabase.co")||h.endsWith(".supabase.co"))return false;}try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"এই লিংকটি খোলা যাচ্ছে না",Toast.LENGTH_SHORT).show();}return true;}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==FILE_REQUEST&&fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(res,data));fileCallback=null;}}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(webView!=null)webView.saveState(out);}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(fileCallback!=null){fileCallback.onReceiveValue(null);fileCallback=null;}if(webView!=null){webView.stopLoading();webView.destroy();}super.onDestroy();}
}